 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like } from "drizzle-orm";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import {
  getDb,
  members,
  organizations,
  organizationSlugRetirements,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

function isWithinHold(retiredAt: string): boolean {
  return Date.now() - new Date(retiredAt).getTime() < ORG_SLUG_HOLD_DAYS * MS_PER_DAY;
}

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * Resolves a slug to its workspace the way every URL and the session layer
 * must: the current slug first, then — for `ORG_SLUG_HOLD_DAYS` days after a
 * rename — the retired slug it replaced.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const retirement = getDb()
    .select()
    .from(organizationSlugRetirements)
    .where(eq(organizationSlugRetirements.slug, slug))
    .get();
  if (!retirement || !isWithinHold(retirement.retiredAt)) return null;

  const owner = getDb()
    .select()
    .from(organizations)
    .where(
      and(eq(organizations.id, retirement.orgId), isNull(organizations.archivedAt)),
    )
    .get();
  return owner ? toOrganization(owner) : null;
}

/**
 * Whether `slug` can become `orgId`'s new current slug: not held as anyone
 * else's current slug (live or deleted), and not retired by anyone else
 * within the hold window. A slug the same org retired itself is always
 * available to it.
 */
export async function isSlugAvailableForRename(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const currentOwner = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(eq(organizations.slug, slug))
    .get();
  if (currentOwner) return false;

  const retirement = getDb()
    .select()
    .from(organizationSlugRetirements)
    .where(eq(organizationSlugRetirements.slug, slug))
    .get();
  if (!retirement) return true;
  if (retirement.orgId === orgId) return true;

  return !isWithinHold(retirement.retiredAt);
}

/** Retires `slug` on behalf of `orgId`, as the slug it is being replaced by a rename. */
export async function retireOrgSlug(orgId: OrgId, slug: string): Promise<void> {
  getDb()
    .insert(organizationSlugRetirements)
    .values({
      id: newId(),
      orgId,
      slug,
      retiredAt: toIsoTimestamp(new Date()),
    })
    .run();
}

/** Un-retires `slug`, when `orgId` renames back to a slug it retired itself. */
export async function releaseOwnSlugRetirement(
  orgId: OrgId,
  slug: string,
): Promise<void> {
  getDb()
    .delete(organizationSlugRetirements)
    .where(
      and(
        eq(organizationSlugRetirements.slug, slug),
        eq(organizationSlugRetirements.orgId, orgId),
      ),
    )
    .run();
}

