/**
 * Renames a workspace's slug — its URL. Per ADR 0005: a chosen slug is
 * refused, never suffixed, when unavailable; the old slug is retired rather
 * than released, so it keeps resolving for `ORG_SLUG_HOLD_DAYS` days; and a
 * rename to the current slug is a no-op that changes and publishes nothing.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (input.slug === org.slug) {
    return org;
  }

  assertValidSlug(input.slug);

  const available = await orgRepo.isSlugAvailableForRename(input.slug, org.id);
  if (!available) {
    throw new InvalidSlugError(input.slug, "is not available");
  }

  await orgRepo.releaseOwnSlugRetirement(org.id, input.slug);
  await orgRepo.retireOrgSlug(org.id, org.slug);

  const updated = await orgRepo.updateOrg(org.id, {
    orgId: org.id,
    slug: input.slug,
  });

  await emit("organization.slug_changed", {
    ...actorEnvelope(actor),
    from: org.slug,
    to: input.slug,
  });

  return updated;
}

